/**
 * Idea Bank types. Mirrors the `ideas` / `idea_sources` rows generated by
 * `supabase gen types` (Supabase MCP → generate_typescript_types) after migrations 0006–0013.
 */
export const IDEA_CATEGORIES = [
  "B2B Services", "Beauty & Personal Care", "Consumer Services", "E-commerce", "EdTech", "FinTech",
  "Food & Beverage", "Healthtech", "Home Services", "Logistics", "Real Estate", "SaaS", "Transportation", "Travel", "Other",
] as const;
export type IdeaCategory = (typeof IDEA_CATEGORIES)[number];
export type IdeaPath = "startup" | "small_business";
export type MarketStatus = "sourced" | "not_found" | "pending" | "ai_estimate";
export type CollectionMode = "rewrite" | "link_only" | "disabled";

export interface IdeaRow {
  id: string;
  title: string;
  summary: string | null;
  who_has_it: string | null;
  why_it_matters: string | null;
  category: IdeaCategory;
  path: IdeaPath;
  source_id: number;
  source_url: string;
  source_key: string;
  source_score: number | null;
  source_score_label: string | null;
  market_segment: string | null;
  market_size_value: number | null;
  market_size_currency: "INR" | "USD" | null;
  market_size_unit: string | null;
  market_geography: string | null;
  market_size_year: number | null;
  growth_rate: number | null;
  growth_type: "YoY" | "CAGR" | null;
  growth_period: string | null;
  market_source_name: string | null;
  market_source_url: string | null;
  market_source_quote: string | null;
  market_status: MarketStatus;
  market_insights: string | null; // AI snapshot: case study, earnings, competition
  market_verified_at: string | null;
  market_verified_by: string | null;
  status: "draft" | "published" | "rejected";
  interest_count: number;
  duplicate_of: string | null;
  duplicate_similarity: number | null;
  created_at: string;
  published_at: string | null;
  reviewed_by: string | null;
}

/** Columns students are granted (see 0006). Never add market_source_quote here. */
export const PUBLIC_IDEA_COLUMNS =
  "id, title, summary, who_has_it, why_it_matters, category, path, source_id, source_url, source_score, source_score_label, market_segment, market_size_value, market_size_currency, market_size_unit, market_geography, market_size_year, growth_rate, growth_type, growth_period, market_source_name, market_source_url, market_status, market_insights, interest_count, published_at";

export type PublicIdea = Omit<IdeaRow, "source_key" | "market_source_quote" | "market_verified_at" | "market_verified_by" | "status" | "duplicate_of" | "duplicate_similarity" | "created_at" | "reviewed_by">
  & { source_name: string };

export interface IdeaSourceRow {
  id: number;
  slug: string;
  name: string;
  homepage_url: string;
  collection_mode: CollectionMode;
  terms_checked_at: string | null;
  terms_notes: string | null;
  last_run_at: string | null;
  last_status: string | null;
}

export const PATH_LABEL: Record<IdeaPath, string> = { startup: "Startup", small_business: "Small business" };
export const IDEA_GOAL = 150;
